import React from "react"
import Awards from "./awards/Awards"
import Featured from "./featured/Featured"

import Hero from "./hero/Hero"
import Location from "./location/Location"
import Price from "./price/Price"
import Recent from "./recent/Recent"
import Team from "./team/Team"
import Projecta from "./project/Project"
import {Helmet} from "react-helmet";
import { useLocation } from "react-router-dom";



const Home = () => {
  const location = useLocation();
  const paths = window.location.pathname;
  const fword = paths[1] + paths[2]

  return (
    <>
    {fword == 'ar' ? 
      <Helmet>
        <title> شركة عقارات زیست العقارية - إقليم كردستان العراق - أربيل </title>
      </Helmet>
      : 
      <Helmet>
        <title>Zest-Property - Property For Sale</title>
        <meta name="keywords" content="Property-For-Sale Sale Property House real estate"/>
        <meta name="dis" content="Find your home from Zest Property,Property For Sale from iraq cheap houses for sale " />
      </Helmet>
      }
      <Hero />
      {/* <Featured /> */}
      <Recent />
      <Awards />
      <Team />
      {/* <Projecta /> */}
      {/* <Location /> */}
    </>
  )
}

export default Home
